 /* 1 · retirada: cayó una cruz */for(const S of G17.sec){const c=N17.cross[S.i];if(c&&c.fallen&&!S.ret){S.ret=1;const to=Math.min(2,S.i+1)===S.i?Math.max(0,S.i-1):Math.min(2,S.i+1);gOrd17(S.i,'retirada',30);const m=gMoveMen17(S.i,to,9,true);for(const q of G17.L)if(q.gr==='mg'&&q.gsec===S.i&&!q.dead17&&!q.down17){const M=q.gmg,b=gFreeBay17(to,null,0,q);if(!b)continue;q.gr='bay';q.gmg=null;q.mgM=null;q.gsec=to;gGo17(q,b,false,true);q.grt.unshift([M.x+3.4,G17.LZ+3.1],[M.x+3.4,G17.LZ])}gSig17(n,'sret',Math.PI,2.8);gSay17(n,'ret'+S.i,'¡Cayó la Cruz '+(S.i+1)+'! ¡Repliegue a la Cruz '+(to+1)+'! ¡Por la trinchera, '+m+' hombres!',0,2.8);return}}
 /* 2 · fuego entrante: cubrirse */for(const S of G17.sec){if(S.ord==='cubrirse')continue;const inc=G17.hot.find(h=>h.sh&&Math.abs(h.x-S.x)<40&&h.t-time>.4);if(inc){gOrd17(S.i,'cubrirse',Math.max(3,inc.t-time+1.2));gSig17(n,'scov',Math.atan2(S.x-p.x,S.z+30-p.z),1.8);gSay17(n,'cov'+S.i,['¡Fuego entrante en la Cruz '+(S.i+1)+'! ¡Cúbranse!','¡Cuerpo a tierra, Cruz '+(S.i+1)+'! ¡Abajo!'][R()*2|0],5,2);return}}
