 /* 3b · tanque encima: los fusileros abajo, que trabaje el antitanque */for(const S of G17.sec){const v=S.vthr;if(!v||!v.g||S.ord==='cubrirse'||time-(S.tkT||-99)<20)continue;if(Math.hypot(v.g.position.x-S.x,v.g.position.z-LZ)<62){S.tkT=time;gOrd17(S.i,'cubrirse',6);gSig17(n,'scov',Math.atan2(v.g.position.x-p.x,v.g.position.z-p.z),1.8);gSay17(n,'tk'+S.i,'¡Tanque encima de la Cruz '+(S.i+1)+'! ¡Abajo! ¡Que lo atienda el antitanque!',0,2.4);return}}
 /* 4 · reubicarse: refuerza la cruz más amenazada con hombres del sector tranquilo */let hi=null,lo=null;for(const S of G17.sec){const k=G17.L.filter(q=>q.gr==='bay'&&q.gsec===S.i&&!q.dead17&&!q.down17).length;S.k=k;if(!hi||S.thr>hi.thr)hi=S;}for(const S of G17.sec)if(S!==hi&&S.thr===0&&S.k>=3&&!N17.cross[S.i].fallen&&(!lo||S.k>lo.k))lo=S;
 if(hi&&lo&&hi.thr>=4&&hi.k<5&&time-(G17.relT||-99)>25){G17.relT=time;const m=gMoveMen17(lo.i,hi.i,2,false);if(m){gOrd17(hi.i,'reubicarse',8);gSig17(n,'sadv',Math.atan2(hi.x-p.x,0.001),2.6);const cb=GN17.cb[lo.i].split(' ').pop();gSay17(n,'rel','¡Cabo '+cb+', '+m+' hombres a la Cruz '+(hi.i+1)+'! ¡Reubíquense, agachados!',0,2.6);return}}
