 /* 6 · recorrer los puestos de mando: va adonde está la amenaza, si no, rota cada tanto */let want=n.gcp;if(hi&&hi.thr>0)want=hi.i;else if(n.gtt<=0){want=(n.gcp+1)%4;n.gtt=22+R()*10}
